SELECT metric,min(value) AS minimum,max(value) AS maximum,uniqExact(hostname) AS hosts,count() AS samples FROM clusterAllReplicas(default,merge('system','^asynchronous_metric_log'))
WHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') AND metric IN ('CGroupMaxCPU','CGroupMemoryTotal','OSMemoryTotal') GROUP BY metric ORDER BY metric LIMIT 10 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=6000000,skip_unavailable_shards=0 FORMAT CSVWithNames
